// Domain types from SPEC §3. Timestamps are ISO 8601 UTC strings; IDs are
// UUID v4 strings generated by the server. Text fields are stored trimmed.

export type ProductRef = {
  /** Display name, 1–200 chars. Never used for identity (SPEC §4.2). */
  readonly name: string;
  readonly category?: string;
  /** dm article number (DAN), digits only, 1–13 chars. */
  readonly dmArticleNumber?: string;
  /** dm product URL, stored normalised (SPEC §4.2). */
  readonly dmUrl?: string;
};

export type Favorite = ProductRef & {
  readonly id: string;
  readonly category: string;
  readonly aliases: readonly string[];
  readonly createdAt: string;
};

export type ListEntry = {
  readonly id: string;
  readonly product: ProductRef;
  readonly favoriteId?: string;
  readonly quantity: number;
  readonly status: "open" | "bought";
  readonly addedAt: string;
  readonly boughtAt?: string;
};

/** Validated `resolve_items` input (SPEC §6.1); text is trimmed, quantity defaulted. */
export type ResolveItemsInput = {
  readonly items: readonly ResolveItemRequest[];
};

export type ResolveItemRequest = {
  readonly term: string;
  readonly quantity: number;
};

export type ResolveResult =
  | {
      readonly term: string;
      readonly quantity: number;
      readonly status: "resolved";
      readonly favorite: Favorite;
    }
  | {
      readonly term: string;
      readonly quantity: number;
      readonly status: "ambiguous";
      readonly candidates: readonly Favorite[];
    }
  | {
      readonly term: string;
      readonly quantity: number;
      readonly status: "unknown";
    };

export type ResolveItemsOutput = {
  readonly results: readonly ResolveResult[];
};

/**
 * Validated `add_to_shopping_list` input (SPEC §6.2). Text fields are
 * trimmed and dm URLs normalised, so equivalent spellings are equal.
 */
export type AddToShoppingListInput = {
  readonly requestId: string;
  readonly items: readonly AddItem[];
};

export type AddItem =
  | { readonly favoriteId: string; readonly quantity: number }
  | { readonly product: ProductRef; readonly quantity: number };

/** Validated `save_favorite` input (SPEC §6.6): trimmed text, normalised dm URL. */
export type SaveFavoriteInput = {
  readonly name: string;
  readonly category: string;
  readonly aliases: readonly string[];
  readonly dmArticleNumber?: string;
  readonly dmUrl?: string;
};

/** Result of `add_to_shopping_list` (SPEC §6.2). */
export type AddResult = {
  readonly requestId: string;
  readonly replayed: boolean;
  /** One per input item, in input order; `quantity` is the entry's new total. */
  readonly entries: readonly AddResultEntry[];
};

export type AddResultEntry = {
  readonly entryId: string;
  readonly name: string;
  readonly quantity: number;
  readonly action: "created" | "merged";
};

export type ProcessedRequest = {
  readonly requestId: string;
  /** SHA-256 of the canonical JSON of the validated request items. */
  readonly payloadHash: string;
  /** The original successful result. */
  readonly result: AddResult;
  readonly processedAt: string;
};

/** The persisted document (SPEC §3). */
export type StoreFile = {
  readonly version: 1;
  readonly favorites: readonly Favorite[];
  readonly list: readonly ListEntry[];
  readonly processedRequests: readonly ProcessedRequest[];
};
